# Terraform Module: S3 + RDS + IAM

## Structure

```
.
├── modules/
│   ├── s3-bucket/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   ├── rds-postgres/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   └── iam-role/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
├── main.tf
├── variables.tf
├── outputs.tf
├── backend.tf
├── dev.tfvars
├── prod.tfvars
└── versions.tf
```

## Root files

### `versions.tf`

```hcl
terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}
```

### `backend.tf`

```hcl
terraform {
  backend "s3" {
    key            = "webapp/terraform.tfstate"
    dynamodb_table = "terraform-locks"
    encrypt        = true
  }
}
```

State is separated per environment via workspace-prefixed keys:

```bash
terraform workspace new dev
terraform workspace new prod
```

### `variables.tf` (root)

```hcl
variable "aws_region" {
  description = "AWS region"
  type        = string
}

variable "environment" {
  description = "Environment name (dev/prod)"
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "project" {
  description = "Project name used for resource naming"
  type        = string
  default     = "webapp"
}

variable "s3_replication_region" {
  description = "Replication target region (prod only, empty to disable)"
  type        = string
  default     = ""
}

variable "db_instance_class" {
  type = string
}

variable "db_multi_az" {
  type = bool
}

variable "db_allocated_storage" {
  type = number
}

variable "db_name" {
  type    = string
  default = "webapp"
}

variable "db_username" {
  type = string
}

variable "db_password" {
  description = "DB master password - pass via TF_VAR or -var-file; never commit plaintext"
  type        = string
  sensitive   = true
}

variable "oidc_provider_arn" {
  description = "IRSA/OIDC provider ARN for trust policy (empty for dev IAM user mode)"
  type        = string
  default     = ""
}

variable "oidc_subject" {
  description = "OIDC subject (service account), e.g. system:serviceaccount:default:webapp"
  type        = string
  default     = ""
}

variable "kms_deletion_days" {
  type    = number
  default = 30
}
```

### `main.tf` (root)

```hcl
locals {
  name_prefix = "${var.project}-${var.environment}"
  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

module "s3_bucket" {
  source = "./modules/s3-bucket"

  name                = "${local.name_prefix}-assets"
  replication_region  = var.s3_replication_region
  tags                = local.common_tags
}

module "rds" {
  source = "./modules/rds-postgres"

  name              = "${local.name_prefix}-db"
  instance_class    = var.db_instance_class
  allocated_storage = var.db_allocated_storage
  multi_az          = var.db_multi_az
  db_name           = var.db_name
  db_username       = var.db_username
  db_password       = var.db_password
  engine_version    = "15"
  tags              = local.common_tags
}

module "iam" {
  source = "./modules/iam-role"

  name            = "${local.name_prefix}-sa-role"
  bucket_arn      = module.s3_bucket.bucket_arn
  use_oidc_trust  = var.oidc_provider_arn != ""
  oidc_provider   = var.oidc_provider_arn
  oidc_subject    = var.oidc_subject
  tags            = local.common_tags
}
```

### `outputs.tf` (root)

```hcl
output "bucket_name" {
  value = module.s3_bucket.bucket_name
}

output "bucket_arn" {
  value = module.s3_bucket.bucket_arn
}

output "db_endpoint" {
  value = module.rds.endpoint
}

output "db_connection_string" {
  description = "Postgres connection string (sensitive)"
  value       = "postgresql://${var.db_username}:${var.db_password}@${module.rds.endpoint}/${var.db_name}"
  sensitive   = true
}

output "iam_role_arn" {
  value = module.iam.role_arn
}
```

## S3 module

### `modules/s3-bucket/variables.tf`

```hcl
variable "name" {
  type = string
}

variable "replication_region" {
  description = "Enable replication to this region if non-empty"
  type        = string
  default     = ""
}

variable "tags" {
  type    = map(string)
  default = {}
}
```

### `modules/s3-bucket/main.tf`

```hcl
resource "aws_s3_bucket" "this" {
  bucket = var.name
  tags   = var.tags
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-region replication (prod)
resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.replication_region != "" ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication[0].arn

  rules {
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

provider "aws" {
  alias  = "replica"
  region = var.replication_region != "" ? var.replication_region : "us-west-2"
}

resource "aws_s3_bucket" "replica" {
  count  = var.replication_region != "" ? 1 : 0
  provider = aws.replica
  bucket = "${var.name}-replica"
  tags   = var.tags
}

resource "aws_s3_bucket_versioning" "replica" {
  count     = var.replication_region != "" ? 1 : 0
  provider  = aws.replica
  bucket    = aws_s3_bucket.replica[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "replication" {
  count = var.replication_region != "" ? 1 : 0
  name  = "${var.name}-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = var.replication_region != "" ? 1 : 0
  name  = "replication"
  role  = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
        Resource = aws_s3_bucket.this.arn
      },
      {
        Effect = "Allow"
        Action = ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging"]
        Resource = "${aws_s3_bucket.this.arn}/*"
      },
      {
        Effect   = "Allow"
        Action   = ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
        Resource = "${aws_s3_bucket.replica[0].arn}/*"
      }
    ]
  })
}
```

### `modules/s3-bucket/outputs.tf`

```hcl
output "bucket_name" {
  value = aws_s3_bucket.this.id
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}
```

## RDS module

### `modules/rds-postgres/variables.tf`

```hcl
variable "name" {
  type = string
}

variable "instance_class" {
  type = string
}

variable "allocated_storage" {
  type = number
}

variable "multi_az" {
  type = bool
}

variable "db_name" {
  type = string
}

variable "db_username" {
  type = string
}

variable "db_password" {
  type      = string
  sensitive = true
}

variable "engine_version" {
  type    = string
  default = "15"
}

variable "backup_retention_days" {
  type    = number
  default = 7
}

variable "deletion_protection" {
  type    = bool
  default = true
}

variable "tags" {
  type    = map(string)
  default = {}
}
```

### `modules/rds-postgres/main.tf`

```hcl
resource "aws_db_subnet_group" "this" {
  name       = "${var.name}-subnet-group"
  subnet_ids = var.subnet_ids
  tags       = var.tags
}

resource "random_password" "master" {
  length  = 24
  special = false
}

resource "aws_secretsmanager_secret" "db_password" {
  name                    = "${var.name}-master-password"
  recovery_window_in_days = 7
  tags                    = var.tags
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id     = aws_secretsmanager_secret.db_password.id
  secret_string = random_password.master.result
}

resource "aws_db_instance" "this" {
  identifier     = var.name
  engine         = "postgres"
  engine_version = var.engine_version
  instance_class = var.instance_class

  db_name  = var.db_name
  username = var.db_username
  password = random_password.master.result
  manage_master_user_password = false

  allocated_storage     = var.allocated_storage
  max_allocated_storage = var.allocated_storage * 2

  multi_az               = var.multi_az
  storage_encrypted      = true
  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false

  backup_retention_period = var.backup_retention_days
  deletion_protection     = var.deletion_protection
  skip_final_snapshot     = false
  final_snapshot_identifier = "${var.name}-final"

  tags = var.tags
}

resource "aws_security_group" "db" {
  name_prefix = "${var.name}-db-"
  vpc_id      = var.vpc_id
  tags        = var.tags
}

resource "aws_security_group_rule" "db_ingress" {
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  security_group_id        = aws_security_group.db.id
  source_security_group_id = var.app_security_group_id
}
```

### `modules/rds-postgres/outputs.tf`

```hcl
output "endpoint" {
  value = aws_db_instance.this.address
}

output "db_instance_arn" {
  value = aws_db_instance.this.arn
}
```

## IAM role module

### `modules/iam-role/variables.tf`

```hcl
variable "name" {
  type = string
}

variable "bucket_arn" {
  type = string
}

variable "use_oidc_trust" {
  type = bool
}

variable "oidc_provider" {
  type    = string
  default = ""
}

variable "oidc_subject" {
  type    = string
  default = ""
}

variable "tags" {
  type    = map(string)
  default = {}
}
```

### `modules/iam-role/main.tf`

```hcl
data "aws_iam_policy_document" "trust" {
  count = var.use_oidc_trust ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider]
    }

    condition {
      test     = "StringEquals"
      variable = "${replace(var.oidc_provider, "https://", "")}:sub"
      values   = [var.oidc_subject]
    }
  }
}

data "aws_iam_policy_document" "trust_ec2" {
  count = var.use_oidc_trust ? 0 : 1

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "this" {
  name = var.name
  tags = var.tags

  assume_role_policy = var.use_oidc_trust
    ? data.aws_iam_policy_document.trust[0].json
    : data.aws_iam_policy_document.trust_ec2[0].json
}

# Least-privilege: read-only bucket access, no wildcards
resource "aws_iam_role_policy" "bucket_access" {
  name = "bucket-read-write"
  role = aws_iam_role.this.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListBucket"
        Effect = "Allow"
        Action = ["s3:ListBucket", "s3:GetBucketLocation"]
        Resource = var.bucket_arn
      },
      {
        Sid      = "ObjectAccess"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
        Resource = "${var.bucket_arn}/*"
      }
    ]
  })
}
```

### `modules/iam-role/outputs.tf`

```hcl
output "role_arn" {
  value = aws_iam_role.this.arn
}

output "role_name" {
  value = aws_iam_role.this.name
}
```

## Environment tfvars

### `dev.tfvars`

```hcl
aws_region          = "us-east-1"
environment         = "dev"
s3_replication_region = ""
db_instance_class   = "db.t3.micro"
db_multi_az         = false
db_allocated_storage = 20
db_username         = "webapp_admin"
```

### `prod.tfvars`

```hcl
aws_region          = "us-east-1"
environment         = "prod"
s3_replication_region = "us-west-2"
db_instance_class   = "db.t3.medium"
db_multi_az         = true
db_allocated_storage = 50
db_username         = "webapp_admin"
oidc_provider_arn   = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE"
oidc_subject        = "system:serviceaccount:default:webapp"
```

## Usage

```bash
# Dev
terraform workspace select dev
terraform init
terraform plan -var-file=dev.tfvars
terraform apply -var-file=dev.tfvars

# Prod — isolated state (separate workspace key) and separate tfvars
terraform workspace select prod
terraform plan -var-file=prod.tfvars -out=prod.tfplan
terraform apply prod.tfplan
```

**Secrets:** `db_password` is passed via environment variable (`TF_VAR_db_password`) or a SOPS-encrypted tfvars file decrypted at apply time — never committed plaintext. Alternatively use `manage_master_user_password = true` to let RDS manage it in Secrets Manager.

## Acceptance criteria mapping

| Criterion | Where |
|---|---|
| Bucket versioning + SSE + no public access | `s3-bucket` module |
| RDS deletion protection, 7d backups, not public | `rds-postgres` module defaults |
| Secret handling | `sensitive` vars + Secrets Manager / SOPS / TF_VAR |
| Least-privilege IAM, no wildcards (prod OIDC trust) | `iam-role` module |
| Env isolation | workspaces + per-env tfvars, independent state keys |
